#include <bits/stdc++.h>
using namespace std;
using i64 = long long;
const i64 MOD = 1000000007;

int readInt() {
    int x = 0, sign = 1;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') sign = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return x * sign;
}

i64 modPow(i64 base, i64 exp) {
    i64 res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

i64 modInverse(i64 x) {
    return modPow(x, MOD - 2);
}

void add(int& x, int y) {
    x = (x + y) % MOD;
    if (x < 0) x += MOD;
}

void subtract(int& x, int y) {
    x = (x - y + MOD) % MOD;
}

void fwht(vector<int>& a, int type) {
    int n = a.size();
    for (int len = 2; len <= n; len <<= 1) {
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < len / 2; j++) {
                int u = a[i + j];
                int v = a[i + j + len / 2];
                if (type == 1) {
                    a[i + j] = (u + v) % MOD;
                } else {
                    a[i + j] = (u - v + MOD) % MOD;
                }
            }
        }
    }
}

int main() {
    int n = readInt();
    vector<vector<int>> p(6, vector<int>(6, 0));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            p[i][j] = (int)((i64)readInt() * modInverse(100) % MOD);
        }
    }

    for (int i = n; i < 6; i++) {
        p[i][i] = 1;
    }

    vector<int> id(64, -1);
    int idx = 0;
    for (int i = 0; i < 64; i++) {
        if (__builtin_popcount(i) == 3) {
            id[i] = idx++;
        }
    }

    vector<int> X(1 << 18, 0), Y(1 << 18, 0);

    for (int mask = 0; mask < (1 << 18); mask++) {
        int m1 = mask & 63;
        int m2 = (mask >> 6) & 63;
        int m3 = (mask >> 12) & 63;

        i64 prob = 1;
        for (int j = 0; j < 6; j++) {
            if (m1 >> j & 1) prob = prob * p[0][j] % MOD;
            else prob = prob * (MOD + 1 - p[0][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m2 >> j & 1) prob = prob * p[1][j] % MOD;
            else prob = prob * (MOD + 1 - p[1][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[2][j] % MOD;
            else prob = prob * (MOD + 1 - p[2][j]) % MOD;
        }

        int combined = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nm = (1 << a) | (1 << b) | (1 << c);
                                combined |= 1 << id[nm];
                            }
                        }
                    }
                }
            }
        }
        add(X[combined], (int)prob);
    }

    for (int mask = 0; mask < (1 << 18); mask++) {
        int m1 = mask & 63;
        int m2 = (mask >> 6) & 63;
        int m3 = (mask >> 12) & 63;

        i64 prob = 1;
        for (int j = 0; j < 6; j++) {
            if (m1 >> j & 1) prob = prob * p[3][j] % MOD;
            else prob = prob * (MOD + 1 - p[3][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m2 >> j & 1) prob = prob * p[4][j] % MOD;
            else prob = prob * (MOD + 1 - p[4][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[5][j] % MOD;
            else prob = prob * (MOD + 1 - p[5][j]) % MOD;
        }

        int combined = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nm = (1 << a) | (1 << b) | (1 << c);
                                nm ^= 63;
                                combined |= 1 << id[nm];
                            }
                        }
                    }
                }
            }
        }
        add(Y[combined], (int)prob);
    }

    fwht(X, 1);
    fwht(Y, 1);

    for (int i = 0; i < (1 << 18); i++) {
        X[i] = (int)((i64)X[i] * Y[i] % MOD);
    }

    fwht(X, -1);

    int ans = 0;
    for (int i = 1; i < (1 << 18); i++) {
        add(ans, X[i]);
    }

    printf("%d\n", ans);
    return 0;
}
